import requests

url = "https://api.example.com/login"

payload = {
    "username": "ada",
    "password": "s3cr3t!"
}
headers = {
    "accept": "application/json",
    "content-type": "application/x-www-form-urlencoded"
}

response = requests.post(url, data=payload, headers=headers)

print(response.text)
